        if not isinstance(num, int) or num <= 1:
            return False
        if num <= 3:
            return True
        if num % 2 == 0 or num % 3 == 0:
            return False
        i = 5
        step = 2
        limit = int(num ** 0.5) + 1
        while i <= limit:
            if num % i == 0:
                return False
            i += step
            step = 6 - step  # alternate between adding 2 and 4 (i.e., 6k±1)
        return True

    return x if _is_prime(n) else y

def double_the_difference(lst):
    """
    Return the sum of squares of non‑negative odd integers in *lst*.
    Non‑integers, negative numbers, and booleans are ignored.
    """
    if not lst:
        return 0
    total = 0
    for x in lst:
        if isinstance(x, int) and not isinstance(x, bool) and x >= 0 and x % 2 == 1:
            total += x * x
    return total

def cycpattern_check(a, b):
    """Return True if b or any of its rotations is a substring of a."""
    # Ensure inputs are strings
    if not isinstance(a, str) or not isinstance(b, str):
        raise TypeError("Both arguments must be strings")
    # Empty pattern matches any string (including empty)
    if b == "":
        return True
    # If pattern longer than text, cannot be a substring
    if len(b) > len(a):
        return False
    # Precompute all rotations of b
    n = len(b)
    # Use a set to avoid duplicate checks for repeated patterns
    rotations = {b[i:] + b[:i] for i in range(n)}
    for rot in rotations:
        if rot in a:
            return True
    return False

def even_odd_count(num):
    """Given an integer, return a tuple (even_count, odd_count) of its digits.

    Handles negative numbers and zero correctly.
    """
    if not isinstance(num, int):
        raise TypeError("Input must be an integer")
    # Zero is a special case: its only digit is 0 (even)
    if num == 0:
        return (1, 0)

    even = odd = 0
    for ch in str(abs(num)):
        digit = ord(ch) - 48  # faster than int(ch)
        if digit & 1:  # odd
            odd += 1
        else:          # even
            even += 1
    return (even, odd)

def right_angle_triangle(a, b, c):
    """
    Return True if the three side lengths can form a right‑angled triangle.
    Handles degenerate or invalid inputs by returning False.
    """
    import math

    # Validate numeric types
    try:
        sides = [float(a), float(b), float(c)]
    except (TypeError, ValueError):
        return False

    # All sides must be positive
    if any(s <= 0 for s in sides):
        return False

    # Triangle inequality must hold
    sides.sort()
    if sides[0] + sides[1] <= sides[2]:
        return False

    # Check Pythagorean theorem with tolerance
    return math.isclose(sides[0] ** 2 + sides[1] ** 2, sides[2] ** 2, rel_tol=1e-9, abs_tol=0.0)

def find_max(words):
    """
    Return the word with the maximum number of unique characters.
    If multiple words share the maximum count, return the lexicographically smallest one.
    For an empty input list, return an empty string.
    """
    if not words:
        return ""

    max_unique = -1
    candidates = []

    for w in words:
        # Ensure we are dealing with a string; skip otherwise
        if not isinstance(w, str):
            continue
        unique_count = len(set(w))
        if unique_count > max_unique:
            max_unique = unique_count
            candidates = [w]
        elif unique_count == max_unique:
            candidates.append(w)

    if not candidates:
        return ""

    return min(candidates)

def solve(s):
    if not any(c.isalpha() for c in s):
        return s[::-1]
    return ''.join(c.swapcase() if c.isalpha() else c for c in s)
